use core.files as files

fn publish(src: String, out: String) -> Void ? IOError {
    files.create_dir_all(out)?
    loop ent in files.walk(src)? {
        if ent.stat.kind == .File {
            target :: files.path_join(out, ent.relative)
            files.copy(ent.path, target)?
        }
    }
    files.write_atomic(files.path_join(out, "index.html"), render_index())?
    return ok(())
}

