//  Why: this package sets panic_budget: 0, and `parse_port` stops on bad input
//  Fix: return `Int ? PortError`, or raise the budget in package.jet

// The wall cannot tell the two kinds of panic apart. This legal
// programmer-error guard (law L2 allows it) burns budget the same way:
fn checked_get(xs: [Int], i: Int) => Int {
    if i >= xs.len() { panic("index {i} is a caller bug") }   // counted like the port panic
    return xs[i]
}

// One function promises it, in the shipped prohibition arrow:
enum PortError { NotANumber(String), OutOfRange(Int) }

pub fn parse_port(raw: String) =[!Panic]=> Int(1..65535) ? PortError {
    n :: Int.parse(raw) ?? return Err(PortError.NotANumber(~raw))
    return Int(1..65535).from_int(n) ?? return Err(PortError.OutOfRange(n))
}

// Or the whole package denies it, in package.jet:
package confkit {
    effects: { deny: [Panic] }
}

// The old panicking body now refuses to compile:
// $ jet check confkit/
// Error [E0749]: `parse_port` can stop, but Panic is denied here
//   --> confkit/src/lib.jet:3
//  Why: the `??` fallback calls `panic` on bad input; `parse_port` and every reachable callee must not stop
//  Fix: return `Int ? PortError` for expected failure, or move a caller bug behind `#Pre` and let callers prove it

// A programmer-error stop stays legal behind a declared contract:
#Pre(i < xs.len(), "index must be in bounds")
fn checked_get(xs: [Int], i: Int) =[!Panic]=> Int {
    return xs[i]   // trap check erases: the #Pre fact proves the index
}

// $ jet check confkit/
